import{_ as t,o as r,c as n,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2019-10-22 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-10-22 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-10-22T00:00:00.000Z","updated":"2019-11-01T00:00:00.000Z","tags":["Ceph","分布式存储","F2FS文件系统","代码优化","功能开发"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-22_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-10-22_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),e={name:"posts/2019/2019-10-22_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function i(l,o,g,_,p,a){return r(),n("div",null,[...o[0]||(o[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph分布式存储项目讨论</p><p><strong>会议时间</strong>： 2019年10月22日</p><p><strong>参会人员</strong>： [参会人员名单]</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph存储优化</strong></p><ol><li><strong>F2FS文件系统</strong>： 讨论了F2FS文件系统在Flash存储优化方面的优势，认为其与Ceph的使用场景非常契合，并计划将其移植到Crimson存储系统。</li><li><strong>Crimson存储系统</strong>： 讨论了F2FS文件系统移植到Crimson存储系统的可行性，并计划进行测试和优化。</li></ol><p><strong>二、代码优化与重构</strong></p><ol><li><strong>命名空间管理</strong>： 讨论了Ceph代码中不同环境（如Crimson、Alien等）使用不同命名空间的问题，提出了统一命名空间和头文件的建议，以提高代码的可读性和可维护性。</li><li><strong>编译时配置问题</strong>： 讨论了Ceph中编译时配置导致的问题，如无法同时构建Diane Store和Alien Store，建议改为运行时配置。</li></ol><p><strong>三、功能开发与测试</strong></p><ol><li><strong>Crimson OS测试</strong>： 讨论了Crimson OS的测试进展，包括测试用例的编写和测试结果的收集。</li><li><strong>异常处理</strong>： 讨论了Ceph中Future对象异常处理的方式，提出了使用异常处理方法替换异常值的建议。</li><li><strong>异步消息传递</strong>： 讨论了异步消息传递模块的开发进展，包括与现有v2版本的兼容性测试和代码清理。</li></ol><p><strong>四、其他事项</strong></p><ol><li><strong>DM时钟服务器</strong>： 讨论了DM时钟服务器的合并进度，以及其对其他模块的影响。</li><li><strong>DBTK与Crimson</strong>： 讨论了将DBTK与Crimson结合使用的可行性，并寻求相关帮助。</li></ol><p><strong>五、行动计划</strong></p><ol><li><strong>Ceph存储优化</strong>： 继续进行F2FS文件系统移植到Crimson存储系统的测试和优化工作。</li><li><strong>代码优化与重构</strong>： 实施统一命名空间和头文件的建议，解决编译时配置问题。</li><li><strong>功能开发与测试</strong>： 完成Crimson OS的测试工作，优化异步消息传递模块。</li><li><strong>其他事项</strong>： 完成DM时钟服务器的合并，探索DBTK与Crimson的结合使用。</li></ol><p><strong>六、会议总结</strong></p><p>本次会议讨论了Ceph分布式存储项目的多个方面，包括存储优化、代码重构、功能开发等。会议明确了后续的工作计划和目标，为项目的顺利进行提供了指导。</p>',17)])])}const m=t(e,[["render",i]]);export{C as __pageData,m as default};
